#pragma once

// V36: Four-real-frame temporal extrapolation.
// The latest four real images yield three *consecutive* motion fields:
//  F0<-F-1 (flowNewest), F-1<-F-2 (flowPrevious), F-2<-F-3 (flowOldest).
// Motion is generated by the unchanged NvOFA/compute pipeline. The presenter
// owns copies of these fields so input-set recycling cannot corrupt prediction.
// This shader is deliberately a low-cost heuristic, not an occlusion/depth model.
static const char kAdaptivePredictionHlsl[] = R"HLSL(
Texture2D src           : register(t0);
Texture2D<float2> flowNewest   : register(t1);
Texture2D<float2> flowPrevious : register(t2);
Texture2D<float2> flowOldest   : register(t3);
SamplerState samp : register(s0);

cbuffer Predict : register(b0) {
    float fraction;
    float sourceW;
    float sourceH;
    float protectRadius;
    float protectFeather;
    float validFlowCount;
};

struct V { float4 p:SV_Position; float2 uv:TEXCOORD0; };
V VS(uint id:SV_VertexID) {
    V o;
    float2 p = float2((id==2)?3.0:-1.0, (id==1)?3.0:-1.0);
    o.p = float4(p,0,1);
    o.uv = float2((p.x+1.0)*0.5, 1.0-(p.y+1.0)*0.5);
    return o;
}

float2 LimitMagnitude(float2 v, float limit) {
    float len = length(v);
    return v * min(1.0, limit / max(len, 0.0001));
}

float4 PS(V i):SV_Target {
    // The real-frame path still uses the native captured color, not predictions.
    [branch] if (fraction <= 0.0) return src.Sample(samp,i.uv);

    const float2 size = max(float2(sourceW,sourceH),float2(1.0,1.0));
    const float t = saturate(fraction);
    float2 v0 = clamp(flowNewest.SampleLevel(samp,i.uv,0),-128.0,128.0);
    float2 projected = v0*t; // identical to the previous V35 shader with one flow

    // One flow field is enough for V35 fallback. Two fields capture acceleration,
    // while three fields capture changing acceleration ("jerk"). Never wait for
    // 4 new frames: use the historical fields already present in GPU memory.
    [branch] if (validFlowCount >= 2.0) {
        // Backtrace previous positions before comparing motion fields. This
        // spatial alignment reduces false acceleration on moving foregrounds.
        float2 uv1 = saturate(i.uv - v0/size);
        float2 v1 = clamp(flowPrevious.SampleLevel(samp,uv1,0),-128.0,128.0);
        float2 a = v0 - v1;
        float limit = min(24.0, 2.0 + length(v0)*0.55);
        float2 cappedAcceleration = LimitMagnitude(a, limit);
        float reliability = 1.0;

        [branch] if (validFlowCount >= 3.0) {
            float2 uv2 = saturate(uv1 - v1/size);
            float2 v2 = clamp(flowOldest.SampleLevel(samp,uv2,0),-128.0,128.0);
            float2 previousAcceleration = v1 - v2;
            float2 jerk = a - previousAcceleration;

            // Sudden direction reversals / flicks make historical acceleration
            // unreliable. Prefer the newest flow rather than aggressive jerk.
            reliability = saturate(1.0 - length(jerk) /
                                   (3.0 + 0.55*length(v0)));
            float2 cappedJerk = LimitMagnitude(jerk, min(9.0,limit*0.3));
            projected += cappedJerk * (t*(t+1.0)*(t+2.0)/6.0)
                         * (0.16*reliability);
        }

        // Light local motion-discontinuity heuristic; NOT full occlusion
        // reconstruction. Reduce the history contribution near motion edges.
        float2 neighborUV = saturate(i.uv + float2(4.0,0.0)/size);
        float2 neighbor = flowNewest.SampleLevel(samp,neighborUV,0);
        float edgeTrust = saturate(1.0 - length(neighbor-v0) /
                                     (2.5 + 0.35*length(v0)));
        projected += cappedAcceleration * (0.5*t*(t+1.0))
                     * (reliability*edgeTrust);
    }

    // Preserve EXACT V35 clamped-velocity behavior when there is only one
    // valid motion field. Bound each axis on multi-frame extrapolation too.
    projected = clamp(projected, -128.0*t, 128.0*t);
    float2 centerDelta = (i.uv-float2(0.5,0.5))*size;
    float radialDistance = length(centerDelta);
    float protect = protectFeather <= 0.01
        ? step(protectRadius,radialDistance)
        : smoothstep(protectRadius,protectRadius+protectFeather,radialDistance);
    float2 uv = saturate(i.uv + projected*protect/size);
    return src.Sample(samp,uv);
}
)HLSL";
